gcU(){return"\u0395\u03b3\u03b3\u03c1\u03b1\u03c6\u03b5\u03af\u03c4\u03b5 \u03b5\u03b4\u03ce!"},
gct(){return"\u03a0\u03c1\u03ce\u03c4\u03b1 \u03b2\u03ae\u03bc\u03b1\u03c4\u03b1"},
gcu(){return"\u0395\u03be\u03b5\u03c1\u03b5\u03cd\u03bd\u03b7\u03c3\u03b7 \u03bc\u03b1\u03b8\u03b7\u03bc\u03ac\u03c4\u03c9\u03bd"},
gcv(){return"\u0391\u03bd\u03ac\u03c0\u03c4\u03c5\u03be\u03b7 \u03bc\u03b1\u03b8\u03b7\u03bc\u03ac\u03c4\u03c9\u03bd"},
gcp(){return"\u039a\u03ac\u03b8\u03b5 \u03bc\u03ac\u03b8\u03b7\u03bc\u03b1 \u03be\u03b5\u03ba\u03b9\u03bd\u03ac \u03bc\u03b5 \u03bc\u03b9\u03b1 \u03b9\u03c3\u03c4\u03bf\u03c1\u03af\u03b1 \u03c0\u03bf\u03c5 \u03c0\u03b5\u03c1\u03b9\u03bb\u03b1\u03bc\u03b2\u03ac\u03bd\u03b5\u03b9 \u03b2\u03af\u03bd\u03c4\u03b5\u03bf, \u03b5\u03b9\u03c3\u03b1\u03b3\u03c9\u03b3\u03ae \u03c3\u03b5 PDF \u03ae podcast, \u03c3\u03c7\u03b5\u03b4\u03b9\u03b1\u03c3\u03bc\u03ad\u03bd\u03b1 \u03b3\u03b9\u03b1 \u03bd\u03b1 \u03c3\u03b1\u03c2 \u03b2\u03bf\u03b7\u03b8\u03ae\u03c3\u03bf\u03c5\u03bd \u03bd\u03b1 \u03ba\u03b1\u03c4\u03b1\u03bd\u03bf\u03ae\u03c3\u03b5\u03c4\u03b5 \u03ba\u03b1\u03b9 \u03bd\u03b1 \u03b1\u03c6\u03bf\u03bc\u03bf\u03b9\u03ce\u03c3\u03b5\u03c4\u03b5 \u03c4\u03b7\u03bd \u03cd\u03bb\u03b7."},
gcq(){return"\u0392\u03b5\u03bb\u03c4\u03b9\u03ce\u03c3\u03c4\u03b5 \u03c4\u03b9\u03c2 \u03b4\u03b5\u03be\u03b9\u03cc\u03c4\u03b7\u03c4\u03ad\u03c2 \u03c3\u03b1\u03c2 \u03bc\u03b5 \u03bc\u03b1\u03b8\u03ae\u03bc\u03b1\u03c4\u03b1 \u03b1\u03c0\u03cc \u03c0\u03b9\u03c3\u03c4\u03bf\u03c0\u03bf\u03b9\u03b7\u03bc\u03ad\u03bd\u03bf\u03c5\u03c2 \u03b5\u03b9\u03b4\u03b9\u03ba\u03bf\u03cd\u03c2 \u03c0\u03bf\u03c5 \u03c3\u03b1\u03c2 \u03b4\u03af\u03bd\u03bf\u03c5\u03bd \u03c4\u03bf \u03c0\u03c1\u03bf\u03b2\u03ac\u03b4\u03b9\u03c3\u03bc\u03b1."},
gcr(){return"\u039e\u03b5\u03ba\u03bb\u03b5\u03b9\u03b4\u03ce\u03c3\u03c4\u03b5 \u03ba\u03ac\u03b8\u03b5 \u03bc\u03ac\u03b8\u03b7\u03bc\u03b1 \u03bc\u03b5 \u03b4\u03b9\u03b1\u03b4\u03c1\u03b1\u03c3\u03c4\u03b9\u03ba\u03ac \u03ba\u03bf\u03c5\u03af\u03b6, \u03ba\u03b1\u03b8\u03b7\u03bb\u03c9\u03c4\u03b9\u03ba\u03ac \u03bc\u03ad\u03c3\u03b1 \u03ba\u03b1\u03b9 \u03c0\u03bb\u03bf\u03cd\u03c3\u03b9\u03bf\u03c5\u03c2 \u03c0\u03cc\u03c1\u03bf\u03c5\u03c2, \u03bc\u03b5 \u03b1\u03c0\u03bf\u03ba\u03bf\u03c1\u03cd\u03c6\u03c9\u03bc\u03b1 \u03ad\u03bd\u03b1 \u03b5\u03c0\u03af\u03c3\u03b7\u03bc\u03bf \u03c0\u03b9\u03c3\u03c4\u03bf\u03c0\u03bf\u03b9\u03b7\u03c4\u03b9\u03ba\u03cc \u03bf\u03bb\u03bf\u03ba\u03bb\u03ae\u03c1\u03c9\u03c3\u03b7\u03c2."},
gdm(){return"\u0391\u03bd \u03ad\u03c7\u03b5\u03c4\u03b5 \u03b5\u03c1\u03c9\u03c4\u03ae\u03c3\u03b5\u03b9\u03c2 \u03b3\u03b9\u03b1 \u03c4\u03b7\u03bd \u03b5\u03c4\u03b1\u03b9\u03c1\u03b5\u03af\u03b1 \u03bc\u03b1\u03c2, \u03bc\u03c0\u03bf\u03c1\u03b5\u03af\u03c4\u03b5 \u03bd\u03b1 \u03bc\u03b1\u03c2 \u03b3\u03c1\u03ac\u03c8\u03b5\u03c4\u03b5 \u03bc\u03ad\u03c3\u03c9 \u03c4\u03b7\u03c2 \u03c0\u03b1\u03c1\u03b1\u03ba\u03ac\u03c4\u03c9 \u03c6\u03cc\u03c1\u03bc\u03b1\u03c2."},
gd8(){return"\u0393\u03c1\u03ac\u03c8\u03c4\u03b5 \u03c4\u03bf \u03bc\u03ae\u03bd\u03c5\u03bc\u03b1 \u03b5\u03b4\u03ce"},
gcX(){return"\u0391\u03c0\u03bf\u03c3\u03c4\u03bf\u03bb\u03ae"},
